// Source/schema qualification only. No auth claims, DDL or audit mutation.
import { writeFile } from "node:fs/promises";
import path from "node:path";
import { credential,own } from "./governance-approval-hosted-20261002.release-20261004.mjs";
const token=await credential("SUPABASE_ACCESS_TOKEN");
const query=`SELECT jsonb_build_object('captured_at',clock_timestamp(),'engine',current_setting('server_version_num')::int,'ledger',(SELECT count(*)::int FROM supabase_migrations.schema_migrations),'latest',(SELECT max(version::text) FROM supabase_migrations.schema_migrations),
'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'body',p.prosrc,'definition',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname IN ('submit_governance_membership_request','decide_governance_membership_request','withdraw_governance_membership_request','governance_access_review_campaign_create','governance_access_review_decide','audit_log_chain','audit_log_block_mutation')) OR (n.nspname='private' AND p.proname IN ('governance_membership_active','governance_membership_record','governance_review_assert_member','governance_review_snapshot','governance_review_can_read','governance_review_row','governance_review_is_admin'))),
'columns',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN ('audit_log','access_review_items','access_review_campaigns') AND a.attnum>0 AND NOT a.attisdropped),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid))) FROM pg_constraint c WHERE c.conrelid IN ('public.audit_log'::regclass,'public.access_review_campaigns'::regclass,'public.access_review_items'::regclass)),
'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))) FROM pg_trigger WHERE tgrelid='public.audit_log'::regclass AND NOT tgisinternal)) AS catalog`;
for(const environment of ["PROD","DEV"]){const ref=environment==="PROD"?"YOUR_PROJECT_REF":"YOUR_PROJECT_REF";const response=await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`,{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({query,read_only:true}),signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error(`Read-only denial schema HTTP${response.status}`);const result=await response.json();const file=path.join(own,`${environment}-DENIAL-CATALOG-${new Date().toISOString().replaceAll(/[:.]/gu,"-")}.json`);await writeFile(file,JSON.stringify({read_only:true,query,result},null,2),{flag:"wx"});console.log(JSON.stringify({environment,evidence:file,ledger:result[0].catalog.ledger,functions:result[0].catalog.functions.length,audit_tenant_nullable:!result[0].catalog.columns.find(c=>c.table==="audit_log"&&c.column==="tenant_id").not_null}));}
